def min_meeting_rooms(intervals):
    if not intervals:
        return 0
    points = sorted(p for s, e in intervals for p in (s, e))
    rooms = best = 0
    for p in points:
        if any(s == p for s, e in intervals):
            rooms += 1
            best = max(best, rooms)
        else:
            rooms -= 1
    return best
